/// <summary>
/// Controller class to send sales order cancelled business event batch job
/// </summary>
class METSendSalesOrderCancelledBusinessEventController extends SysOperationServiceController
{
}

Method.Source:
/// <summary>
/// Description
/// </summary>
/// <returns>class description</returns>
public static ClassDescription description()
{
    return "@MET:SOCancellationNotification";
}

/// <summary>
/// dialog caption
/// </summary>
/// <param name="_dialogCaption">A <c>LabelType</c> Extended Data Type.</param>
/// <returns>A <c>LabelType</c> Extended Data Type.</returns>
// Caption shown on the Dialog.
public LabelType parmDialogCaption(LabelType _dialogCaption = dialogCaption)
{
    return METSendSalesOrderCancelledBusinessEventController::description();
}

    /// <summary>
    /// create new instance of the class
    /// </summary>
    protected void new()
    {
        super();

        this.parmClassName(classStr(METSendSalesOrderCancelledBusinessEventService));
        this.parmMethodName(methodStr(METSendSalesOrderCancelledBusinessEventService, process));
    }

/// <summary>
/// Constructor method to create new instance of the class
/// </summary>
/// <returns>
/// An object of the <c>METSendSalesOrderCancelledBusinessEventController</c> class.
/// </returns>
public static METSendSalesOrderCancelledBusinessEventController construct()
{
    return new METSendSalesOrderCancelledBusinessEventController();
}

/// <summary>
/// Main controller method
/// parmShowDialog is true by default
/// </summary>
/// <param name = "_args">Args</param>
public static void main(Args _args)
{
    METSendSalesOrderCancelledBusinessEventController controller = METSendSalesOrderCancelledBusinessEventController::construct();
    
    controller.parmExecutionMode(SysOperationExecutionMode::Synchronous);
    controller.startOperation();
}

/// <summary>
/// Can run in new session
/// </summary>
/// <returns>
/// true if can run in new session; otherwise, false.
/// </returns>
protected boolean canRunInNewSession()
{
    return true;
}
